// HasTemplate applies the HasEdge predicate on the "template" edge.
func HasTemplate() predicate.AIPromptTemplateVersion {
	return predicate.AIPromptTemplateVersion(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TemplateTable, TemplateColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTemplateWith applies the HasEdge predicate on the "template" edge with a given conditions (other predicates).
func HasTemplateWith(preds ...predicate.AIPromptTemplate) predicate.AIPromptTemplateVersion {
	return predicate.AIPromptTemplateVersion(func(s *sql.Selector) {
		step := newTemplateStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AIPromptTemplateVersion) predicate.AIPromptTemplateVersion {
	return predicate.AIPromptTemplateVersion(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AIPromptTemplateVersion) predicate.AIPromptTemplateVersion {
	return predicate.AIPromptTemplateVersion(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AIPromptTemplateVersion) predicate.AIPromptTemplateVersion {
	return predicate.AIPromptTemplateVersion(sql.NotPredicates(p))
}
